def make(r):
    (ident, segment, org, role, scope, title_ru, title_en, need_ru, need_en,
     question_ru, question_en, modules, deliver_ru, deliver_en, price, weeks) = r
    return {
        "id": ident,
        "segment": segment,
        "buyer_org_type": org,
        "buyer_role": role,
        "jurisdiction_scope": scope,
        "title_ru": title_ru,
        "title_en": title_en,
        "need_hypothesis_ru": need_ru,
        "need_hypothesis_en": need_en,
        "question_ru": question_ru,
        "question_en": question_en,
        "deliverables_ru": deliver_ru,
        "deliverables_en": deliver_en,
        "modules": modules,
        "duration_weeks": weeks,
        "fixed_price_usd": price,
        "price_terms_ru": f"Фиксированная list price за перечисленный scope: {price:,} USD, без НДС; сторонние лицензии и вне-scope работы отдельно.".replace(",", " "),
        "price_terms_en": f"Fixed list price for the stated scope: USD {price:,}, taxes excluded; this is not a market benchmark or client-budget claim; third-party licences and out-of-scope work excluded.".replace(",", " "),
        "assumptions_ru": ["Данные клиента — только агрегированные и добровольно предоставленные; допустимы публичные данные.",
                           "OSINT_ONLY: лицензируемые источники не включены в цену без отдельного письменного разрешения."],
        "assumptions_en": ["Client data is aggregated and voluntarily provided; public data may be used.",
                            "OSINT_ONLY: licensed sources are excluded unless separately authorized in writing."],
        "exclusions_ru": ["Не является прогнозом, инвестиционной рекомендацией или юридическим заключением.",
                           "Нет гарантии экономии, точности или решения инвестиционного комитета."],
        "exclusions_en": ["Not a forecast, investment recommendation or legal opinion.",
                           "No guarantee of savings, accuracy or investment-committee outcome."],
        "evidence_status": "HYPOTHESIS",
        "not_client": True,
        "sent": False,
        "status": "DRAFT",
    }

payload = {
    "schema": "amfe.commercial_offers.v1",
    "created": "2026-11-23",
    "status": "DRAFT",
    "currency": "USD",
    "taxes_included": False,
    "offers_count": len(ROWS),
    "rules": ["fixed_list_price_not_market_benchmark", "public_org_types_and_role_buyers_only",
              "hypotheses_not_clients", "no_outreach_without_human_approval", "RESEARCH_ONLY_admission_false"],
    "offers": [make(row) for row in ROWS],
}
OUT.parent.mkdir(parents=True, exist_ok=True)
OUT.write_text(json.dumps(payload, ensure_ascii=False, indent=1) + "\n", encoding="utf-8", newline="\n")
print("wrote", len(payload["offers"]), "offers")

